from collections import Counter

def bordered_rect(grid, border=1):
    """The subgrid bounded by the rectangle whose frame cells all equal border."""
    rows = [i for i, r in enumerate(grid) if border in r]
    cols = [j for j in range(len(grid[0])) if any(r[j] == border for r in grid)]
    return [r[cols[0]:cols[-1] + 1] for r in grid[rows[0]:rows[-1] + 1]]

def dihedral(grid, name):
    """One of the 8 symmetry variants: id, rot180, fh, fv, T, T_fh, T_fv, T180."""
    a = np.array(grid)
    v = {'id': a, 'rot180': a[::-1, ::-1], 'fh': a[:, ::-1], 'fv': a[::-1, :],
         'T': a.T, 'T_fh': a.T[:, ::-1], 'T_fv': a.T[::-1, :], 'T180': a.T[::-1, ::-1]}
    return [[int(x) for x in r] for r in v[name]]

def dihedral_matching(grid, target_pos):
    """The unique dihedral variant placing each color at target_pos[color]; None if none fits."""
    a = np.array(grid)
    v = {'id': a, 'rot180': a[::-1, ::-1], 'fh': a[:, ::-1], 'fv': a[::-1, :],
         'T': a.T, 'T_fh': a.T[:, ::-1], 'T_fv': a.T[::-1, :], 'T180': a.T[::-1, ::-1]}
    for name, g in v.items():
        p = {(i, j): int(x) for i, r in enumerate(g) for j, x in enumerate(r)}
        if all(p.get(xy) == c for c, xy in target_pos.items()):
            return name
    return None

def singleton_positions(grid, exclude=(0,)):
    """Map each color appearing exactly once in the grid to its (row, col)."""
    cnt = Counter(v for r in grid for v in r)
    return {v: (i, j) for i, r in enumerate(grid) for j, v in enumerate(r)
            if cnt[v] == 1 and v not in exclude}

def scatter_cells(grid, inside, exclude=(0, 1)):
    """Map each color of the single non-background cells outside region `inside(i,j)` to its position."""
    return {v: (i, j) for i, r in enumerate(grid) for j, v in enumerate(r)
            if v not in exclude and not inside(i, j)}
