def transform(grid):
    """The 1-bordered rectangle under the unique dihedral transform placing its
    once-appearing colors at the L-pattern of the scattered single cells (anchor at (1,1))."""
    A = bordered_rect(grid, 1)
    h, w = len(A), len(A[0])
    inside = lambda i, j: 0 <= i < h and 0 <= j < w
    pos = singleton_positions(A, exclude=(0, 1))
    sc = scatter_cells(grid, inside)
    o = min(sc.values())
    rel = {c: (i - o[0], j - o[1]) for c, (i, j) in sc.items()}
    anchor = [c for c, (dr, dc) in rel.items() if (dr, dc) == (0, 0)][0]
    a = pos[anchor]
    target = {c: (a[0] + dr, a[1] + dc) for c, (dr, dc) in rel.items()}
    return dihedral(A, dihedral_matching(A, target))
